const fs = require('fs');
const path = require('path');
const { execSync } = require('child_process');

console.log('1. Compilando App Web com Vite...');
execSync('npm run build', { stdio: 'inherit' });

const distPath = path.resolve(__dirname, '..', 'dist');
const htmlFile = fs.readFileSync(path.join(distPath, 'index.html'), 'utf8');
const assets = fs.readdirSync(path.join(distPath, 'assets'));
const cssFile = assets.find(f => f.endsWith('.css'));
const jsFile = assets.find(f => f.endsWith('.js'));

const cssContent = cssFile ? fs.readFileSync(path.join(distPath, 'assets', cssFile), 'utf8') : '';
let jsContent = jsFile ? fs.readFileSync(path.join(distPath, 'assets', jsFile), 'utf8') : '';

// Escapar </script> para evitar fechamento prematuro da tag
jsContent = jsContent.replace(/<\/script>/gi, '<\\/script>');

// Limpar tags externas
let cleanHtml = htmlFile;
cleanHtml = cleanHtml.replace(/<link rel="stylesheet"[^>]*>/gi, '');
cleanHtml = cleanHtml.replace(/<script type="module"[^>]*><\/script>/gi, '');

// Injetar CSS e Polyfills + JS App dentro do HTML completo
const injectedHead = `
<style id="app-styles">
${cssContent}
</style>
<script>
  window.__MOBILE_APP__ = true;
  if (typeof window.matchMedia !== 'function') {
    window.matchMedia = function(q) {
      return {
        matches: false,
        media: q,
        onchange: null,
        addListener: function() {},
        removeListener: function() {},
        addEventListener: function() {},
        removeEventListener: function() {},
        dispatchEvent: function() { return false; }
      };
    };
  }
  try {
    var _t = '__storage_probe__';
    window.localStorage.setItem(_t, '1');
    window.localStorage.removeItem(_t);
  } catch (e) {
    var _mem = {};
    window.localStorage = {
      getItem: function(k) { return _mem.hasOwnProperty(k) ? _mem[k] : null; },
      setItem: function(k, v) { _mem[k] = String(v); },
      removeItem: function(k) { delete _mem[k]; },
      clear: function() { _mem = {}; },
      key: function(i) { return Object.keys(_mem)[i] || null; },
      get length() { return Object.keys(_mem).length; }
    };
  }
</script>
</head>`;

cleanHtml = cleanHtml.replace('</head>', injectedHead);

// Injetar o script do aplicativo antes do final do body
const scriptTag = `
<script type="module">
${jsContent}
</script>
</body>`;

cleanHtml = cleanHtml.replace('</body>', scriptTag);

// Exportar HTML e JS
const outputContent = `// Auto-generated by build-bundle.js
export const INLINE_HTML = ${JSON.stringify(cleanHtml)};
export const INLINE_JS = ${JSON.stringify(jsContent)};
`;

fs.writeFileSync(path.join(__dirname, 'src', 'htmlBundle.ts'), outputContent, 'utf8');
console.log('Bundle exportado para mobile-react-native/src/htmlBundle.ts com sucesso!');
